pub fn attach(&mut self, id: &SessionIdentity, key: &ClientPublicKey, grant: Option<&str>) -> Result<()> {
    let granted = match &self.grant_verifier {
        Some(v) => v.verify(id, &key.key_id, grant),
        None => false,
    };
    if !granted {
        return Err(BridgeError::new("grant_invalid: scope grant missing or invalid"));
    }
    let sid = id.session_id.as_str();
    if self.sessions.contains_key(sid) || !self.storage.read_log(sid)?.is_empty() {
        return Err(BridgeError::new("session already exists (I6)"));
    }
    self.storage.register_key(&key.key_id, &key.scheme, &key.material)?;
    self.commit(
        sid,
        vec![(
            Kind::ATTACHED,
            json!({
                "principal_id": id.principal_id,
                "authority_scope": id.authority_scope,
                "task_lineage": id.task_lineage,
                "client_key_id": key.key_id,
                "scope_version": 0,
            }),
        )],
    )?;
    Ok(())
}

pub fn grant(&self, identity: &SessionIdentity, key_id: &str) -> String {
    hex::encode(self.signing.sign(&grant_message(identity, key_id)).to_bytes())
}

fn verify(&self, identity: &SessionIdentity, key_id: &str, grant: Option<&str>) -> bool {
    match grant {
        Some(g) => Ed25519Verifier.verify(SCHEME_ED25519, &self.operator_public_key, &grant_message(identity, key_id), g),
        None => false,
    }
}

pub fn scheme(&self) -> &'static str {
    match self.signer {
        KeySigner::Ed25519(_) => SCHEME_ED25519,
        KeySigner::P256(_) => SCHEME_ECDSA_P256,
    }
}
